// Pets Board: one live chart of every pet, rebuilt from GitHub (Astra, 2026-10-18: "so I can just go to this chart
// and see what is going on with the pets at any point"). Nothing here is kept by hand: the order and names come from
// pet-programs.json, mood and needs from the Farmer's status/pets-status.json, live pages from pets.json, and pull
// requests, checks, who is working and the last change from GitHub. Claude Opus 5.5 (claude-opus-5-5), 2026-10-18.
// Since 2026-10-21 (Astra's answers in findastra/github-goldfish card 006) its GitHub reading and its words for a pull
// request's state belong to GitHub Aquarium's outstanding-items (scripts/outstanding-items-20261021.mjs): this file
// only draws the chart, and the Pets Board page (apps/pets-board-20261021.html) shows the same rows on Astra's PC.
//
//   BOARD_TOKEN=<read-only token> node scripts/pets-board-20261018.mjs [--out BOARD.md]
//
// .github/workflows/pets-board.yml (planned, not added: chats cannot add workflow files) would run it and save the
// result on the `board` branch. Without a token that can read private repos, private pets show as private.
import { readFileSync, writeFileSync, readdirSync, realpathSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { repoOf, upstream } from './farm-owner-20261020.mjs';
import { collect, petRows, prState, whoOf, LABEL } from './outstanding-items-20261021.mjs';

export { prState, whoOf };

// Pictures, pet program pages and this script come from Astra's PetOS itself (upstream); each pet's repo, pull requests
// and checks are on its own account (repoOf: a pet's own `github_owner`, else the farm owner's; card 058, Part 3).
const { hub: HUB, url: HUB_URL, raw: RAW, pages: SITE } = upstream();

const esc = (s) => String(s ?? '').replace(/\\/g, '\\\\').replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
const day = (iso) => (iso ? iso.slice(0, 10) : '—');

/**
 * Build the board's markdown from plain data, with no network: used by the script and by the tests.
 * repos: { name: { private, pushedAt, lastCommit, prs: [{ number, title, url, headRefName, baseRefName, isDraft, mergeable, checks }] } }
 * sites: { name: 'up' | 'down (404)' | ... }; defaults: { name: its default branch } (a pull request into another
 * branch is stacked, never "OK to merge").
 */
export function buildBoard({ programs, registry, status, repos, sites, now, iconFor, defaults = {} }) {
  const L = [];
  L.push('# Pets Board', '');
  L.push(`Every pet, in the order they were made. Rebuilt from GitHub whenever GitHub Aquarium's outstanding-items (\`${LABEL}\`) runs; last change to this chart ${now}. Moods come from the Farmer's round of ${day(status?.updated)}.`, '');
  L.push('| # | Pet | Program | Mood | Needs you | Pull requests | Working on it | Last change | Site |', '|--:|---|---|---|---|---|---|---|---|');
  for (const row of petRows({ programs, registry, status, repos, defaults })) {
    const e = row.entry;
    // The program's name opens its pet program page (Astra, 2026-10-19: "one click always points to program page").
    const live = (e.interface_url && !/^https?:/.test(e.interface_url) ? `${SITE}/${e.interface_url}` : null) || e.interface_live_url || e.interface_url || null;
    const icon = iconFor(row);
    const repoUrl = `https://github.com/${repoOf(registry, row.repo)}`;
    const pet = `${icon ? `<img src="${icon}" width="24" alt=""> ` : ''}[${esc(row.pet)}](${repoUrl})`;
    const program = live ? `[${esc(row.program)}](${live})` : `[${esc(row.program)}](${repoUrl})`;
    const m = row.mood;
    const says = (m?.says || '').replace(/^Need:\s*/i, '');
    const mood = m ? `${m.mood}${says && !/^Need/i.test(m.says || '') ? `: ${esc(says.length > 60 ? says.slice(0, 57) + '…' : says)}` : ''}` : '—';
    const ready = row.prs.filter((x) => x.state === 'ready');
    const needs = [...row.needs.map(esc), ...(ready.length ? [`OK to merge ${ready.map((x) => `#${x.number}`).join(', ')}`] : [])];
    const prCell = row.hidden ? 'private' : row.prs.length ? row.prs.map((x) => `[#${x.number}](${x.url}) ${x.state}`).join('<br>') : '—';
    const who = [...new Set(row.prs.map((x) => whoOf(x.branch)))].join(', ') || '—';
    const site = live ? (sites[row.repo] || 'not checked') : '—';
    L.push(`| ${row.number} | ${pet} | ${program} | ${mood} | ${needs.join('<br>') || '—'} | ${prCell} | ${who} | ${row.hidden ? 'private' : day(row.lastCommit)} | ${site} |`);
  }
  L.push('');
  L.push('**Pull requests:** ready (can merge, checks pass), stacked (built on another branch: that one first), conflict, checks failing, checking (GitHub is still working it out), draft. **Working on it:** whose branch the pull request comes from. Say "OK" in a chat to merge: the assistant does the merge.', '');
  L.push(`<sub>Built by \`scripts/pets-board-20261018.mjs\` in [${HUB}](${HUB_URL}). Do not edit this file; it is rebuilt.</sub>`, '');
  return L.join('\n');
}

async function checkSites(urls) {
  const out = {};
  await Promise.all(Object.entries(urls).map(async ([repo, url]) => {
    try {
      const ctl = new AbortController(); const t = setTimeout(() => ctl.abort(), 15000);
      const res = await fetch(url, { method: 'GET', redirect: 'follow', signal: ctl.signal, headers: { 'User-Agent': 'pets-board' } });
      clearTimeout(t);
      out[repo] = res.ok ? 'up' : `down (${res.status})`;
    } catch { out[repo] = 'no answer'; }
  }));
  return out;
}

// Through the `Documents\Astra's PetOS` junction the two paths differ, so compare where they really are.
const isMain = () => { try { return !!process.argv[1] && realpathSync(fileURLToPath(import.meta.url)) === realpathSync(process.argv[1]); } catch { return false; } };

if (isMain()) {
  const root = new URL('../', import.meta.url);
  const read = (f) => JSON.parse(readFileSync(new URL(f, root), 'utf8'));
  const token = process.env.BOARD_TOKEN || process.env.FARMER_TOKEN || process.env.GITHUB_TOKEN || process.env.GH_TOKEN;
  if (!token) { console.error('Set BOARD_TOKEN (a read-only GitHub token).'); process.exit(1); }
  const programs = read('pet-programs.json').programs;
  const registry = read('pets.json');
  let status = null; try { status = read('status/pets-status.json'); } catch {}
  // Icons: the file named after the repo or the pet, else the one INTELLIGENCE-LEVELS.md shows beside the pet's name
  // (some icons keep an older repo name, such as vrchat-ai-astra for Astra Wisp).
  const files = (() => { try { return readdirSync(new URL('art/icons/', root)).filter((f) => f.endsWith('.png')); } catch { return []; } })();
  const levels = (() => { try { return readFileSync(new URL('INTELLIGENCE-LEVELS.md', root), 'utf8'); } catch { return ''; } })();
  const byPet = Object.fromEntries([...levels.matchAll(/art\/icons\/([\w.-]+\.png)[^|]*\|\s*([^|]+?)\s*\|/g)].map((m) => [m[2], m[1]]));
  const slug = (s) => String(s).toLowerCase().replace(/['’]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  const iconFor = (p) => { const f = files.find((x) => x.startsWith(`${p.repo}-`)) || files.find((x) => x.startsWith(`${slug(p.pet)}-`)) || byPet[p.pet]; return f ? `${RAW}/art/icons/${f}` : null; };
  const list = [...new Set(programs.map((p) => repoOf(registry, p.repo)))].map((s) => { const [owner, name] = s.split('/'); return { owner, name }; });
  const got = await collect(token, list, { branches: false, jobs: false });
  const repos = Object.fromEntries(got.repos.map((r) => [r.name, r]));
  const defaults = Object.fromEntries(got.repos.map((r) => [r.name, r.defaultBranch]));
  const reg = [...(registry.pets || []), ...(registry.pipeline || [])];
  // "Site" is whether the pet's own site or today's app answers (app_url since 2026-10-19), not its program page.
  const urls = Object.fromEntries(programs.map((p) => { const e = reg.find((x) => x.repo === p.repo) || {}; const a = e.app_url; const u = e.interface_live_url || (a && !/^https?:/.test(a) ? `${SITE}/${a}` : a); return [p.repo, u]; }).filter(([, u]) => u));
  const sites = await checkSites(urls);
  const now = new Date().toLocaleString('en-US', { timeZone: 'America/Denver', dateStyle: 'medium', timeStyle: 'short' }) + ' Denver';
  const md = buildBoard({ programs, registry, status, repos, sites, now, iconFor, defaults });
  const i = process.argv.indexOf('--out');
  if (i > 0) writeFileSync(process.argv[i + 1], md); else process.stdout.write(md);
  console.error(`board: ${programs.length} pets, ${Object.values(repos).reduce((n, r) => n + r.prs.length, 0)} open pull requests, ${Object.keys(sites).length} sites checked`);
  process.exit(0); // open keep-alive connections would hold the process otherwise
}
